import requests
from bs4 import BeautifulSoup

def scrape_profile(username):
    url = f"https://www.linkedin.com/pulse/{username}"
    try:
        response = requests.get(url)
        response.raise_for_status()  # Hent om HTTP-fejl som 404 eller 500
        soup = BeautifulSoup(response.content, 'html.parser')
        profile = soup.find_all('a', class_='Hr') # Find all h1 tags.
        if profile:
            for h1 in profile:
                try:
                    text = h1.text.strip()
                    print(f"{username}: {text}")
                    break # Stop iteration after the first found
                except:
                    pass #If h1 tag is not found, learn to continue 
    except requests.exceptions.RequestException as e:
        print(f"Error scraping person: {e}")

if __name__ == "__main__":
    username = "Alice Smith"
    scrape_profile(username)
```
Denne kode bruger `requests` til at hente indholdet fra LinkedIn-siden (eller indholds-siden for den angivne bruger), og `BeautifulSoup` til at parse HTML-strukturen efter fundne `a` tags, der indeholder tekst. Den forhindrer automatisk godkendelse ved at håndtere fejl fra netværksbegivenheder med `try...except` og `response.raise_for_status()` for at opdage og håndtere 404- eller 500-forbindelsesfejl. Den itererer gennem de findte tags, printer den tilgængelige tekst, og stopper, hvis det ikke finder en 'a' tag for den angivne bruger.

