import requests
from bs4 import BeautifulSoup

def scrape_reddit_data(subreddit):
    try:
        url = f"https://www.reddit.com/r/{subreddit}/search/?query={subreddit}"
        response = requests.get(url)
        response.raise_for_status()  # Raise HTTPError for bad responses (4xx or 5xx)
        soup = BeautifulSoup(response.content, 'html.parser')

        data = []
        for i, item in enumerate(soup.find_all('div', class_='item')):
            try:
                name = item.find('span', class_='title').text.strip()
                user = item.find('p', class_='user-name').text.strip()
                creation_date = item.find('span', class_='creation-date').text.strip()

                data.append({
                    'Name': name,
                    'User': user,
                    'Creation Date': creation_date
                })
            except AttributeError as e:
                print(f"Problemer med at finde spartanvinden for item {i+1}: {e}")
                continue # Skip to the next item if a particular item is unidentifiable.

        return data

    except requests.exceptions.RequestException as e:
        print(f"Fejl ved forbindelse: {e}")
        return []
    except Exception as e:
        print(f"En uventet fejl opstod: {e}")
        return []



if __name__ == "__main__":
    subreddit = "r/aww" # Eksempel: r/aww
    data = scrape_reddit_data(subreddit)

    if data:
        print(f"Data gemt fra {subreddit}:")
        for item in data:
            print(f"  Navn: {item['Name']}")
            print(f"  Bruger: {item['User']}")
            print(f"  Oprettet Dato: {item['Creation Date']}")
            print("-" * 20)
    else:
        print("Ingen data gemt fra denne subreddit.")
